**File:** `components/screens-components/smart-search-bar.tsx:31–97`

`searchField`, `searchRegistry`, and the inner `TextRenderer` component are defined **inside the render function body**. `TextRenderer` is a new function identity on every render, so React treats it as a brand-new component type and fully **unmounts and remounts** the `<AppTextField>` on every parent re-render — losing focus state and triggering layout.

```tsx
// PROBLEM — new object + new component type every render
const searchField: TextField<SearchValues> = { ... };
const searchRegistry: Partial<FieldRegistry> = {
  text: ({ field, control, disabled }) => {
    const TextRenderer = ({ field: rhf, fieldState }: any) => ( // ← created inside render
      <AppTextField ... />
    );
    return <Controller render={TextRenderer} />;
  },
};
```

**Fix:** Move `searchField` to module level (it is static). Extract `TextRenderer` to a stable component outside `SmartSearchBar`.

```tsx
// module level — created once
const SEARCH_FIELD: TextField<SearchValues> = {
  name: 'query',
  type: 'text',
  placeholder: 'Smart search everything...',
  props: { autoCapitalize: 'none', autoCorrect: false },
};

// stable component — no remount on parent re-render
function SearchTextRenderer({ field: rhf, fieldState, ...adornments }: any) {
  return (
    <AppTextField
      value={rhf.value ?? ''}
      onChangeText={rhf.onChange}
      onBlur={rhf.onBlur}
      errorText={fieldState.error?.message}
      {...adornments}
    />
  );
}
```

