**File:** `components/shared/app-text/app-text.tsx:72–102`

Each prop (`align`, `muted`, `italic`, `transform`, `underline`, `strike`, `fontSize`, `weight`) triggers its own `useMemo`. For text that uses none of these props (the common case), that is 8 memoized computations that all return `undefined`. Consolidating into a single `useMemo` reduces hook overhead.

```tsx
// CURRENT — 8 separate useMemo calls
const weightStyle  = useMemo(() => ..., [resolvedWeight]);
const alignStyle   = useMemo(() => ..., [align]);
const mutedStyle   = useMemo(() => ..., [muted, defaults.mutedOpacity]);
// ...5 more

// BETTER — single useMemo, same deps array content
const derivedStyles = useMemo(() => {
  const weight    = resolvedWeight ? getWeightStyle(resolvedWeight) : undefined;
  const alignS    = align ? { textAlign: align } : undefined;
  const mutedS    = muted ? { opacity: defaults.mutedOpacity } : undefined;
  const italicS   = italic ? { fontStyle: 'italic' } : undefined;
  const transS    = transform ? { textTransform: transform } : undefined;
  const fontSizeS = fontSize ? { fontSize } : undefined;
  const decoLine  = underline && strike ? 'underline line-through'
                  : underline ? 'underline' : strike ? 'line-through' : undefined;
  const decoS     = decoLine ? { textDecorationLine: decoLine } : undefined;
  return [weight, alignS, mutedS, italicS, transS, fontSizeS, decoS];
}, [resolvedWeight, align, muted, defaults.mutedOpacity, italic, transform, fontSize, underline, strike]);
```

