**File:** `contexts/theme.context.tsx:58–59`

```tsx
// Called on every render of every consumer when outside a ThemeProvider
const fallbackSetScheme = () => undefined;    // new ref every call
const fallbackToggleScheme = () => undefined; // new ref every call
```

**Fix:** Hoist to module level.

```tsx
const _noop = () => undefined;

export function useThemeContext() {
  const context = useContext(ThemeContext);
  const deviceScheme = useColorScheme();
  const fallbackScheme: ThemeScheme = deviceScheme === 'dark' ? 'dark' : 'light';
  return context ?? {
    scheme: fallbackScheme,
    tokens: fallbackScheme === 'dark' ? darkTokens : lightTokens,
    setScheme: _noop,
    toggleScheme: _noop,
  };
}
```

